// Every custom command registered in `lib.rs`'s `generate_handler!` must be
// listed in `COMMANDS` below: declaring a command in the `AppManifest` makes
// Tauri's ACL gate it per window, and `tauri-build` autogenerates an
// `allow-<command>` / `deny-<command>` permission pair for each entry into
// `permissions/autogenerated/` (slugified: underscores become dashes).
//
// Capabilities in `capabilities/*.json` then grant those `allow-*` permissions
// per window (`main`, `pill`, `quickadd`): each window gets only the commands
// its own code invokes. `core/tests/acl.rs` keeps the handler list, this
// manifest and the capability grants in sync.
const COMMANDS: &[&str] = &[
    "deeplink_take_pending",
    "google_oauth_start",
    "google_oauth_revoke",
    "google_oauth_cancel",
    "notify_show",
    "desktop_backdrop",
    "quickadd_get_config",
    "quickadd_set_shortcut",
    "quickadd_focus_main",
    "idle_seconds",
    "tray_sync",
    "desktop_launched_at_sign_in",
    "desktop_show_main",
    "pill_focus_main",
    "pill_main_focused",
    "pill_visibility_changed",
    "chat_key_status",
    "chat_key_set",
    "chat_key_clear",
    "chat_stream",
    "chat_cancel",
    "chat_complete",
    "chat_memories_list",
    "chat_memories_apply",
    "chat_memories_delete",
    "chat_memories_clear",
    "engram_settings_get",
    "engram_settings_set",
    "engram_sync_now",
    "engram_status",
];

fn main() {
    tauri_build::try_build(
        tauri_build::Attributes::new()
            .app_manifest(tauri_build::AppManifest::new().commands(COMMANDS)),
    )
    .expect("failed to run tauri-build");
}
